#include "kernel/lmh_executeService.h"
namespace hype::lmh { namespace { struct Entry{hcpp::u32 process_id;ExecuteHandler handler;void* context;}; constexpr hcpp::size_t capacity=8; Entry entries[capacity]; hcpp::size_t count; } void execute_service_initialize() noexcept {count=0;for(auto&e:entries)e={};} bool execute_service_register(hcpp::u32 process_id,ExecuteHandler handler,void* context) noexcept {if(process_id==0||handler==nullptr||count>=capacity)return false;entries[count++]={process_id,handler,context};return true;} hcpp::u32 execute_service_run(const ExecuteRequest& request) noexcept {if(!execute_request_valid(request))return 0xFFFFFFFF;for(hcpp::size_t i=0;i<count;++i)if(entries[i].process_id==request.process_id)return entries[i].handler(entries[i].context,request);return 0xFFFFFFFE;} }
